// JusPrin's synchronous, GUI-thread observer seam for authoritative committed
// project changes. Fork-owned; Orca code reaches it through the neutral
// forwarding header src/slic3r/GUI/ProjectState.hpp.

#include <cstdint>
#include <functional>
#include <map>
#include <memory>
#include <utility>
