void HeaderButton::activate(bool from_keyboard)
{
    if (!IsEnabled()) return;
    if (from_keyboard && !m_row_action_label.empty()) {
        invoke_row_action();
        return;
    }
    m_keyboard_activated = from_keyboard;
    wxCommandEvent event(wxEVT_BUTTON, GetId());
